package com.musab.dosyayoneticisi;
import android.app.*;import android.os.*;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.widget.*;import androidx.core.content.FileProvider;import java.io.*;
public class MusabImageViewerActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);File f=new File(getIntent().getStringExtra("path"));LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(Color.BLACK);TextView t=new TextView(this);t.setText("Musab Görsel Görüntüleyici  •  "+f.getName());t.setTextColor(Color.WHITE);t.setTextSize(18);t.setPadding(16,16,16,16);r.addView(t);ImageView iv=new ImageView(this);iv.setScaleType(ImageView.ScaleType.FIT_CENTER);try{Uri u=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",f);iv.setImageURI(u);}catch(Exception e){t.setText("Görsel açılamadı: "+e.getMessage());}r.addView(iv,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}}